public protocol GemGatewayProtocol: AnyObject, Sendable {
    
    func getAddressStatus(chain: Chain, address: String) async throws  -> [AddressStatus]
    
    func getBalanceCoin(chain: Chain, address: String) async throws  -> GemAssetBalance
    
    func getBalanceStaking(chain: Chain, address: String) async throws  -> GemAssetBalance?
    
    func getBalanceTokens(chain: Chain, address: String, tokenIds: [String]) async throws  -> [GemAssetBalance]
    
    func getBlockNumber(chain: Chain) async throws  -> UInt64
    
    func getCandlesticks(chain: Chain, symbol: String, period: String) async throws  -> [GemChartCandleStick]
    
    func getChainId(chain: Chain) async throws  -> String
    
    func getFee(chain: Chain, input: GemTransactionLoadInput, provider: GemGatewayEstimateFee) async throws  -> GemTransactionLoadFee?
    
    func getFeeRates(chain: Chain, input: GemTransactionInputType) async throws  -> [GemFeeRate]
    
    func getIsTokenAddress(chain: Chain, tokenId: String) async throws  -> Bool
    
    func getNodeStatus(chain: Chain, url: String) async throws  -> NodeStatus
    
    func getPerpetualsData(chain: Chain) async throws  -> [GemPerpetualData]
    
    func getPositions(chain: Chain, address: String) async throws  -> GemPerpetualPositionsSummary
    
    func getStakingDelegations(chain: Chain, address: String) async throws  -> [GemDelegationBase]
    
    func getStakingValidators(chain: Chain, apy: Double?) async throws  -> [GemDelegationValidator]
    
    func getTokenData(chain: Chain, tokenId: String) async throws  -> GemAsset
    
    func getTransactionLoad(chain: Chain, input: GemTransactionLoadInput, provider: GemGatewayEstimateFee) async throws  -> GemTransactionData
    
    func getTransactionPreload(chain: Chain, input: GemTransactionPreloadInput) async throws  -> GemTransactionLoadMetadata
    
    func getTransactionScan(chain: Chain, input: GemTransactionPreloadInput) async throws  -> ScanTransaction?
    
    func getTransactionStatus(chain: Chain, request: GemTransactionStateRequest) async throws  -> TransactionUpdate
    
    func getUtxos(chain: Chain, address: String) async throws  -> [GemUtxo]
    
    func transactionBroadcast(chain: Chain, data: String, options: BroadcastOptions) async throws  -> String
    
}
open class GemGateway: GemGatewayProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_gemstone_fn_clone_gemgateway(self.handle, $0) }
    }
public convenience init(provider: AlienProvider, preferences: GemPreferences, securePreferences: GemPreferences, apiUrl: String) {
    let handle =
        try! rustCall() {
    uniffi_gemstone_fn_constructor_gemgateway_new(
        FfiConverterTypeAlienProvider_lower(provider),
        FfiConverterTypeGemPreferences_lower(preferences),
        FfiConverterTypeGemPreferences_lower(securePreferences),
        FfiConverterString.lower(apiUrl),$0
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        try! rustCall { uniffi_gemstone_fn_free_gemgateway(handle, $0) }
    }

    

    
