        switch variant {
        
        case 1: return .signMessage(chain: try FfiConverterTypeChain.read(from: &buf), signType: try FfiConverterTypeSignDigestType.read(from: &buf), data: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .signTransaction(chain: try FfiConverterTypeChain.read(from: &buf), transactionType: try FfiConverterTypeWalletConnectTransactionType.read(from: &buf), data: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .sendTransaction(chain: try FfiConverterTypeChain.read(from: &buf), transactionType: try FfiConverterTypeWalletConnectTransactionType.read(from: &buf), data: try FfiConverterString.read(from: &buf)
        )
        
